-- ---------- Habilidades (BNCC) ----------------------------------------
INSERT INTO habilidade (id, componente_id, ano_escolar, anos_bncc, descricao, unidade_tematica, grupo, fonte) VALUES
-- 2º ano — Matemática
('EF02MA01', 'MAT', 2, '2º ano', 'Comparar e ordenar números naturais (até a ordem de centenas) pela compreensão de características do sistema de numeração decimal (valor posicional e função do zero).', 'Números', 'Sistema de numeração', 'BNCC (MEC, 2018)'),
('EF02MA05', 'MAT', 2, '2º ano', 'Construir fatos básicos da adição e subtração e utilizá-los no cálculo mental ou escrito.', 'Números', 'Cálculo e fatos básicos', 'BNCC (MEC, 2018)'),
('EF02MA06', 'MAT', 2, '2º ano', 'Resolver e elaborar problemas de adição e de subtração, envolvendo números de até três ordens, com os significados de juntar, acrescentar, separar, retirar, utilizando estratégias pessoais ou convencionais.', 'Números', 'Resolução de problemas', 'BNCC (MEC, 2018)'),
('EF02MA07', 'MAT', 2, '2º ano', 'Resolver e elaborar problemas de multiplicação (por 2, 3, 4 e 5) com a ideia de adição de parcelas iguais por meio de estratégias e formas de registro pessoais, utilizando ou não suporte de imagens e/ou material manipulável.', 'Números', 'Resolução de problemas', 'BNCC (MEC, 2018)'),
-- 2º ano — Língua Portuguesa
('EF12LP01', 'LP', 2, '1º e 2º anos', 'Ler palavras novas com precisão na decodificação, no caso de palavras de uso frequente, ler globalmente, por memorização.', 'Leitura/escuta', 'Alfabetização', 'BNCC (MEC, 2018)'),
('EF02LP04', 'LP', 2, '2º ano', 'Ler e escrever corretamente palavras com sílabas CV, V, CVC, CCV, identificando que existem vogais em todas as sílabas.', 'Análise linguística/semiótica (Alfabetização)', 'Alfabetização', 'BNCC (MEC, 2018)'),
('EF15LP01', 'LP', 2, '1º ao 5º ano', 'Identificar a função social de textos que circulam em campos da vida social dos quais participa cotidianamente (a casa, a rua, a comunidade, a escola) e nas mídias impressa, de massa e digital, reconhecendo para que foram produzidos, onde circulam, quem os produziu e a quem se destinam.', 'Leitura/escuta', 'Compreensão leitora', 'BNCC (MEC, 2018)'),
('EF15LP03', 'LP', 2, '1º ao 5º ano', 'Localizar informações explícitas em textos.', 'Leitura/escuta', 'Compreensão leitora', 'BNCC (MEC, 2018)'),
-- 5º ano — Matemática
('EF05MA03', 'MAT', 5, '5º ano', 'Identificar e representar frações (menores e maiores que a unidade), associando-as ao resultado de uma divisão ou à ideia de parte de um todo, utilizando a reta numérica como recurso.', 'Números', 'Frações', 'BNCC (MEC, 2018)'),
('EF05MA04', 'MAT', 5, '5º ano', 'Identificar frações equivalentes.', 'Números', 'Frações', 'BNCC (MEC, 2018)'),
('EF05MA05', 'MAT', 5, '5º ano', 'Comparar e ordenar números racionais positivos (representações fracionária e decimal), relacionando-os a pontos na reta numérica.', 'Números', 'Frações', 'BNCC (MEC, 2018)'),
('EF05MA07', 'MAT', 5, '5º ano', 'Resolver e elaborar problemas de adição e subtração com números naturais e com números racionais, cuja representação decimal seja finita, utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', 'Números', 'Resolução de problemas', 'BNCC (MEC, 2018)'),
('EF05MA08', 'MAT', 5, '5º ano', 'Resolver e elaborar problemas de multiplicação e divisão com números naturais e com números racionais cuja representação decimal é finita (com multiplicador natural e divisor natural e diferente de zero), utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.', 'Números', 'Resolução de problemas', 'BNCC (MEC, 2018)'),
-- 5º ano — Língua Portuguesa
('EF35LP03', 'LP', 5, '3º ao 5º ano', 'Identificar a ideia central do texto, demonstrando compreensão global.', 'Leitura/escuta', 'Compreensão leitora', 'BNCC (MEC, 2018)'),
('EF35LP04', 'LP', 5, '3º ao 5º ano', 'Inferir informações implícitas nos textos lidos.', 'Leitura/escuta', 'Inferência', 'BNCC (MEC, 2018)'),
('EF35LP05', 'LP', 5, '3º ao 5º ano', 'Inferir o sentido de palavras ou expressões desconhecidas em textos, com base no contexto da frase ou do texto.', 'Leitura/escuta', 'Inferência', 'BNCC (MEC, 2018)'),
('EF35LP06', 'LP', 5, '3º ao 5º ano', 'Recuperar relações entre partes de um texto, identificando substituições lexicais (de substantivos por sinônimos) ou pronominais (uso de pronomes anafóricos – pessoais, possessivos, demonstrativos) que contribuem para a continuidade do texto.', 'Leitura/escuta', 'Coesão textual', 'BNCC (MEC, 2018)'),
-- 9º ano — Matemática
('EF09MA05', 'MAT', 9, '9º ano', 'Resolver e elaborar problemas que envolvam porcentagens, com a ideia de aplicação de percentuais sucessivos e a determinação das taxas percentuais, preferencialmente com o uso de tecnologias digitais, no contexto da educação financeira.', 'Números', 'Resolução de problemas', 'BNCC (MEC, 2018)'),
('EF09MA06', 'MAT', 9, '9º ano', 'Compreender as funções como relações de dependência unívoca entre duas variáveis e suas representações numérica, algébrica e gráfica e utilizar esse conceito para analisar situações que envolvam relações funcionais entre duas variáveis.', 'Álgebra', 'Álgebra e funções', 'BNCC (MEC, 2018)'),
('EF09MA09', 'MAT', 9, '9º ano', 'Compreender os processos de fatoração de expressões algébricas, com base em suas relações com os produtos notáveis, para resolver e elaborar problemas que possam ser representados por equações polinomiais do 2º grau.', 'Álgebra', 'Álgebra e funções', 'BNCC (MEC, 2018)'),
('EF09MA14', 'MAT', 9, '9º ano', 'Resolver e elaborar problemas de aplicação do teorema de Pitágoras ou das relações de proporcionalidade envolvendo retas paralelas cortadas por secantes.', 'Geometria', 'Geometria', 'BNCC (MEC, 2018)'),
-- 9º ano — Língua Portuguesa
('EF69LP03', 'LP', 9, '6º ao 9º ano', 'Identificar, em notícias, o fato central, suas principais circunstâncias e eventuais decorrências; em reportagens e fotorreportagens o fato ou a temática retratada e a perspectiva de abordagem, em entrevistas os principais temas/subtemas abordados, explicações dadas ou teses defendidas em relação a esses subtemas; em tirinhas, memes, charge, a crítica, ironia ou humor presente.', 'Leitura', 'Compreensão leitora', 'BNCC (MEC, 2018)'),
('EF69LP05', 'LP', 9, '6º ao 9º ano', 'Inferir e justificar, em textos multissemióticos – tirinhas, charges, memes, gifs etc. –, o efeito de humor, ironia e/ou crítica pelo uso ambíguo de palavras, expressões ou imagens ambíguas, de clichês, de recursos iconográficos, de pontuação etc.', 'Leitura', 'Inferência', 'BNCC (MEC, 2018)'),
('EF89LP04', 'LP', 9, '8º e 9º anos', 'Identificar e avaliar teses/opiniões/posicionamentos explícitos e implícitos, argumentos e contra-argumentos em textos argumentativos do campo (carta de leitor, comentário, artigo de opinião, resenha crítica etc.), posicionando-se frente à questão controversa de forma sustentada.', 'Leitura', 'Argumentação', 'BNCC (MEC, 2018)');

