-- ---------- Estratégias pedagógicas -----------------------------------
INSERT INTO estrategia (id, titulo, tipo, nivel, objetivo, como_aplicar, materiais, como_acompanhar, quando_reavaliar, duracao_semanas, perfil_indicado) VALUES
('EST-FR1', 'Frações com material concreto (tiras e discos de frações)', 'MATERIAL_CONCRETO', 'AMBOS',
 'Construir o significado de fração como parte de um todo e como divisão, partindo da manipulação antes da representação simbólica.',
 'Comece com tiras de papel do mesmo tamanho: dobre em 2, 4 e 8 partes e peça que o estudante nomeie cada parte.|Peça que represente a mesma quantidade com desenho e depois com a escrita numérica (ex.: 3/4).|Proponha situações do cotidiano (dividir um bolo, uma pizza, uma barra de chocolate) e registre as frações encontradas.|Finalize com a transposição para a reta numérica, localizando frações já manipuladas.',
 'Tiras de papel, discos de frações em EVA ou papelão, lápis de cor, reta numérica impressa.',
 'Registre, a cada encontro, se o estudante: nomeia a fração manipulada; passa do concreto para o desenho; escreve a fração corretamente. Use uma ficha simples com "sim / com apoio / ainda não".',
 'Após 3 a 4 semanas, aplique 4 a 5 itens equivalentes aos do descritor avaliado.', 4, 'ATENCAO'),
('EST-FR2', 'Reta numérica na sala: localizar e comparar frações', 'SEQUENCIA_DIDATICA', 'AMBOS',
 'Desenvolver a compreensão de frações como números, com posição na reta, permitindo comparar e ordenar.',
 'Monte uma reta numérica no chão ou na parede (barbante e prendedores) entre 0 e 2.|Distribua cartões com frações e decimais e peça que os estudantes os posicionem, justificando.|Discuta por que 1/2 e 2/4 ocupam o mesmo lugar.|Proponha desafios em duplas: "qual é maior?" com justificativa escrita.',
 'Barbante, prendedores, cartões com frações e decimais.',
 'Observe as justificativas: o estudante usa a ideia de partes iguais ou apenas compara numeradores? Registre exemplos de falas.',
 'Ao final da sequência (cerca de 3 semanas), reavalie com itens de comparação e ordenação.', 3, 'DESENVOLVIMENTO'),
('EST-FR3', 'Dominó de frações equivalentes', 'REFORCO', 'AMBOS',
 'Consolidar o reconhecimento de frações equivalentes por meio de jogo com diferentes representações.',
 'Apresente o dominó com peças que combinam representações (desenho, fração, decimal).|Jogue em grupos de 3 ou 4, pedindo que cada jogada seja explicada em voz alta.|Ao final, peça que cada estudante registre três pares de equivalentes encontrados.',
 'Dominó de frações (impresso ou confeccionado pela turma).',
 'Recolha os registros finais e verifique se as equivalências estão corretas e justificadas.',
 'Após 2 semanas de uso semanal do jogo.', 2, 'TODOS'),
('EST-RP1', 'Resolução de problemas em quatro etapas', 'SEQUENCIA_DIDATICA', 'AMBOS',
 'Desenvolver procedimentos de leitura, planejamento e verificação na resolução de problemas.',
 'Apresente um problema e leia em voz alta, destacando a pergunta.|Peça que o estudante explique com suas palavras o que precisa descobrir.|Planeje a estratégia (desenho, tabela, operação) antes de calcular.|Execute e verifique: a resposta faz sentido na situação?',
 'Banco de problemas contextualizados (feira, transporte, compras no bairro).',
 'Use uma rubrica com as quatro etapas e registre em qual etapa o estudante encontra mais dificuldade.',
 'Após 4 semanas, reavalie com problemas do mesmo tipo e grau de complexidade.', 4, 'TODOS'),
('EST-RP2', 'Cálculo mental e estimativa (10 minutos diários)', 'REFORCO', 'TURMA',
 'Ampliar o repertório de estratégias de cálculo e de estimativa.',
 'Reserve 10 minutos no início da aula para um desafio de cálculo mental.|Socialize diferentes estratégias usadas pelos estudantes.|Registre no quadro as estratégias mais eficientes.',
 'Cartões com operações, quadro.',
 'Acompanhe semanalmente a quantidade de estratégias diferentes que cada estudante consegue explicar.',
 'Após 4 semanas de prática regular.', 4, 'DESENVOLVIMENTO'),
('EST-RP3', 'Problemas com material manipulável e registro pictórico', 'MATERIAL_CONCRETO', 'AMBOS',
 'Apoiar a compreensão dos significados das operações por meio de manipulação e desenho.',
 'Apresente o problema com objetos (tampinhas, palitos).|Peça que o estudante represente a situação com desenho.|Só então proponha o registro com números e sinais.',
 'Tampinhas, palitos, fichas.',
 'Registre se o estudante consegue representar a situação sem os objetos (apenas com desenho).',
 'Após 3 semanas.', 3, 'ATENCAO'),
('EST-NU1', 'Quadro valor-lugar e material dourado', 'MATERIAL_CONCRETO', 'AMBOS',
 'Compreender o valor posicional e a função do zero no sistema de numeração decimal.',
 'Represente números com material dourado.|Transfira para o quadro valor-lugar.|Compare números justificando pela posição dos algarismos.',
 'Material dourado, quadro valor-lugar.',
 'Verifique se o estudante explica a comparação usando centenas, dezenas e unidades.',
 'Após 3 semanas.', 3, 'ATENCAO'),
('EST-LE1', 'Leitura com perguntas inferenciais (antes, durante e depois)', 'LEITURA', 'AMBOS',
 'Desenvolver estratégias de compreensão que vão além da informação explícita.',
 'Antes da leitura: levante hipóteses a partir do título e das imagens.|Durante: pause em trechos-chave e pergunte "o que o texto quer dizer, mesmo sem dizer diretamente?".|Depois: peça que o estudante indique a pista do texto que sustenta sua resposta.',
 'Textos curtos de gêneros variados (fábulas, notícias infantis, tirinhas).',
 'Registre se o estudante aponta pistas textuais para justificar inferências.',
 'Após 4 semanas, com itens de inferência em textos novos.', 4, 'TODOS'),
('EST-LE2', 'Glossário contextual: descobrir o sentido pela pista', 'LEITURA', 'AMBOS',
 'Inferir o sentido de palavras desconhecidas a partir do contexto.',
 'Selecione palavras pouco familiares em um texto.|Peça hipóteses de sentido antes de consultar o dicionário.|Compare a hipótese com o sentido no dicionário e discuta as pistas usadas.',
 'Textos selecionados, dicionário escolar, cartaz de glossário da turma.',
 'Acompanhe o número de hipóteses adequadas ao contexto em cada atividade.',
 'Após 3 semanas.', 3, 'TODOS'),
('EST-LE3', 'Mapa de referências: quem é quem no texto', 'LEITURA', 'AMBOS',
 'Reconhecer substituições lexicais e pronominais que garantem a continuidade do texto.',
 'Leia um texto curto e circule os pronomes e sinônimos.|Ligue cada um à palavra a que se refere, com setas.|Reescreva um trecho trocando referências e discuta o efeito.',
 'Textos impressos, lápis de cor.',
 'Verifique a correção das ligações feitas pelo estudante.',
 'Após 3 semanas.', 3, 'TODOS'),
('EST-AL1', 'Consciência fonológica com alfabeto móvel', 'MATERIAL_CONCRETO', 'AMBOS',
 'Apoiar a decodificação e a escrita de palavras com diferentes estruturas silábicas.',
 'Trabalhe com palavras do universo da turma.|Monte e desmonte palavras com alfabeto móvel, observando as sílabas.|Proponha trocas de letras para formar novas palavras.',
 'Alfabeto móvel, fichas de palavras e imagens.',
 'Registre semanalmente as estruturas silábicas que o estudante já lê e escreve com autonomia.',
 'Após 4 semanas.', 4, 'ATENCAO'),
('EST-AL2', 'Leitura compartilhada de gêneros do cotidiano', 'LEITURA', 'TURMA',
 'Ampliar a familiaridade com textos que circulam no cotidiano e localizar informações.',
 'Leia em voz alta bilhetes, convites, listas e receitas.|Pergunte quem escreveu, para quem e para quê.|Peça que os estudantes localizem informações específicas.',
 'Textos reais do cotidiano (convites, receitas, avisos).',
 'Registre a autonomia na localização de informações.',
 'Após 3 semanas.', 3, 'TODOS'),
('EST-AR1', 'Debate regrado e quadro tese–argumento', 'SEQUENCIA_DIDATICA', 'TURMA',
 'Identificar e avaliar teses e argumentos, posicionando-se de forma sustentada.',
 'Leia um artigo de opinião sobre tema do bairro ou da cidade.|Preencha coletivamente um quadro com tese, argumentos e contra-argumentos.|Organize um debate regrado com papéis definidos.',
 'Artigos de opinião, quadro impresso.',
 'Avalie os quadros preenchidos e a qualidade dos argumentos no debate.',
 'Após 4 semanas.', 4, 'TODOS'),
('EST-AG1', 'Funções a partir de situações reais (tabelas e gráficos)', 'SEQUENCIA_DIDATICA', 'TURMA',
 'Compreender funções como relações de dependência entre variáveis.',
 'Parta de situações do cotidiano (tarifa de ônibus, consumo de água).|Construa tabelas e identifique a regularidade.|Represente em gráfico e, por fim, em expressão algébrica.',
 'Contas de consumo fictícias, papel quadriculado.',
 'Verifique se o estudante transita entre tabela, gráfico e expressão.',
 'Após 4 semanas.', 4, 'TODOS'),
('EST-GE1', 'Pitágoras com malha quadriculada e medições', 'MATERIAL_CONCRETO', 'TURMA',
 'Compreender e aplicar o teorema de Pitágoras em situações-problema.',
 'Construa quadrados sobre os lados de triângulos retângulos em malha quadriculada.|Compare as áreas e formule a relação.|Resolva problemas práticos de medição na escola.',
 'Malha quadriculada, régua, trena.',
 'Acompanhe a resolução dos problemas práticos.',
 'Após 3 semanas.', 3, 'TODOS'),
('EST-PC1', 'Educação financeira: porcentagens em encartes', 'SEQUENCIA_DIDATICA', 'TURMA',
 'Resolver problemas com porcentagens em contextos de consumo.',
 'Use encartes de supermercado para calcular descontos.|Discuta percentuais sucessivos (desconto sobre desconto).|Compare ofertas com uso de calculadora.',
 'Encartes, calculadora.',
 'Verifique a correção dos cálculos e das justificativas.',
 'Após 3 semanas.', 3, 'TODOS'),
('EST-RA1', 'Reavaliação direcionada curta (itens equivalentes)', 'REAVALIACAO', 'AMBOS',
 'Verificar, com poucos itens, se houve avanço na habilidade trabalhada.',
 'Selecione 4 a 5 itens equivalentes aos do descritor avaliado.|Aplique em momento tranquilo, com tempo suficiente.|Registre acertos e compare com a avaliação anterior, sabendo que instrumentos diferentes não são diretamente comparáveis.',
 'Itens equivalentes elaborados pela equipe pedagógica.',
 'Registre o resultado no sistema como reavaliação direcionada.',
 'Ao final do período de intervenção.', 1, 'TODOS');

